import React, { useEffect, useRef, useState } from "react";
import { createChart, CrosshairMode } from "lightweight-charts";
import { EMA, RSI, MACD } from "technicalindicators";

// Helper for formatting API dates for lightweight-charts
const formatTime = (dateStr) => {
  // If the backend returns "YYYY-MM-DD", lightweight-charts accepts it directly
  return dateStr;
};

export default function TradingChart({ symbol, timeframe }) {
  const containerRef = useRef(null);
  const chartRef = useRef(null);
  const seriesMap = useRef({});
  const dataRef = useRef([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const activeIndicators = {
    EMA: true,
    RSI: true,
  };

  // 1. Initialize Chart
  useEffect(() => {
    if (!containerRef.current) return undefined;

    const chart = createChart(containerRef.current, {
      layout: {
        background: { color: "#131722" },
        textColor: "#d1d4dc",
        fontSize: 12,
      },
      grid: {
        vertLines: { color: "#2a2e39" },
        horzLines: { color: "#2a2e39" },
      },
      crosshair: {
        mode: CrosshairMode.Normal,
      },
      rightPriceScale: {
        borderColor: "#2a2e39",
        autoScale: true,
        scaleMargins: { top: 0.1, bottom: 0.25 },
      },
      timeScale: {
        borderColor: "#2a2e39",
        timeVisible: true,
        secondsVisible: false,
      },
    });

    const candleSeries = chart.addCandlestickSeries({
      upColor: "#26a69a",
      downColor: "#ef5350",
      borderVisible: false,
      wickUpColor: "#26a69a",
      wickDownColor: "#ef5350",
    });

    const volumeSeries = chart.addHistogramSeries({
      color: "rgba(38, 166, 154, 0.5)",
      priceFormat: { type: "volume" },
      priceScaleId: "",
      scaleMargins: { top: 0.8, bottom: 0 },
    });

    chartRef.current = chart;
    seriesMap.current.candles = candleSeries;
    seriesMap.current.volume = volumeSeries;

    const handleResize = () => {
      if (containerRef.current && chart) {
        chart.applyOptions({
          width: containerRef.current.clientWidth,
          height: containerRef.current.clientHeight,
        });
      }
    };

    window.addEventListener("resize", handleResize);
    handleResize();

    return () => {
      window.removeEventListener("resize", handleResize);
      chart.remove();
    };
  }, []);

  // 2. Fetch Live Historical Data from Backend
  useEffect(() => {
    if (!chartRef.current || !seriesMap.current.candles || !symbol) return;

    const fetchData = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await fetch(`/api/stocks/${symbol}/history`);
        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
        const result = await response.json();

        if (!result.history || result.history.length === 0) {
          throw new Error("No historical data available for this symbol.");
        }

        // Format and sort data (ascending by time)
        const sortedData = result.history
          .map(item => ({
            time: item.date, // YYYY-MM-DD
            open: parseFloat(item.open),
            high: parseFloat(item.high),
            low: parseFloat(item.low),
            close: parseFloat(item.close),
            value: parseFloat(item.volume),
          }))
          .sort((a, b) => new Date(a.time) - new Date(b.time));

        dataRef.current = sortedData;
        const { candles, volume } = seriesMap.current;
        const chart = chartRef.current;

        candles.setData(sortedData);
        volume.setData(
          sortedData.map(d => ({
            time: d.time,
            value: d.value,
            color: d.close > d.open ? "rgba(38, 166, 154, 0.5)" : "rgba(239, 83, 80, 0.5)",
          }))
        );

        // Indicator Calculations
        const closePrices = sortedData.map(d => d.close);

        // Clean old indicator series
        Object.keys(seriesMap.current).forEach(key => {
          if (!["candles", "volume"].includes(key) && seriesMap.current[key]) {
            try { chart.removeSeries(seriesMap.current[key]); } catch (e) {}
            delete seriesMap.current[key];
          }
        });

        const mapIndicatorData = (vals) => {
          const res = [];
          const offset = sortedData.length - vals.length;
          for (let i = 0; i < vals.length; i++) {
            if (vals[i] != null && !isNaN(vals[i])) {
              res.push({ time: sortedData[i + offset].time, value: vals[i] });
            }
          }
          return res;
        };

        if (activeIndicators.EMA) {
          const emaVals = EMA.calculate({ period: 20, values: closePrices });
          const emaSeries = chart.addLineSeries({
            color: "#ff9800",
            lineWidth: 2,
            title: "EMA (20)",
          });
          emaSeries.setData(mapIndicatorData(emaVals));
          seriesMap.current.ema = emaSeries;
        }

        if (activeIndicators.RSI) {
          const rsiVals = RSI.calculate({ period: 14, values: closePrices });
          const rsiSeries = chart.addLineSeries({
            color: "#9c27b0",
            lineWidth: 2,
            title: "RSI (14)",
            priceScaleId: "rsi",
          });
          chart.priceScale("rsi").applyOptions({
            scaleMargins: { top: 0.8, bottom: 0 },
          });
          rsiSeries.setData(mapIndicatorData(rsiVals));
          seriesMap.current.rsi = rsiSeries;
        }

        chart.timeScale().fitContent();
        setLoading(false);
      } catch (err) {
        console.error("Failed to fetch live chart data:", err);
        setError(err.message);
        setLoading(false);
      }
    };

    fetchData();
  }, [symbol, timeframe]);

  return (
    <div className="trading-chart-container" style={{ width: "100%", height: "100%", position: "relative" }}>
      {loading && (
        <div style={{ position: "absolute", inset: 0, zIndex: 10, display: "grid", placeItems: "center", background: "rgba(19, 23, 34, 0.8)", color: "#d1d4dc" }}>
          Loading Live Data...
        </div>
      )}
      {error && (
        <div style={{ position: "absolute", inset: 0, zIndex: 10, display: "grid", placeItems: "center", background: "rgba(19, 23, 34, 0.9)", color: "#ef5350", padding: "20px", textAlign: "center" }}>
          Error: {error}
        </div>
      )}
      <div 
        ref={containerRef} 
        style={{ width: "100%", height: "100%" }} 
      />
    </div>
  );
}
